@rule("s20", "s1", otherwise="NotMentioned")
def query_result():
    return entailment_label(True)

@scope("s2")
def applicability():
    return True

@rule("s2", "s1", otherwise="NotMentioned")
def receiving_party_obligation():
    return "Contradiction" if "reverse engineer" in "Receiving Party shall not reverse engineer any objects which embody Disclosing Party's Confidential Information." else "NotMentioned"

@rule("s3", "s1", otherwise="NotMentioned")
def confidential_information_definition():
    return "Entailment" if "Confidential Information" in "Confidential Information means any business and/or personally identifiable information relating to Tompkins Cortland Community College's students, employees or other parties contained in files or storage systems to which the Company will be provided access by Tompkins Cortland Community College." else "NotMentioned"

@rule("s4", "s1", otherwise="NotMentioned")
def confidential_information_scope():
    return "Entailment" if "Confidential Information" in "Confidential Information shall include, without limitation, printed or electronically recorded matter, personally identifiable information, customer and employee information, business information, and other information of a non-public nature." else "NotMentioned"

@rule("s5", "s1", otherwise="NotMentioned")
def ownership_of_confidential_information():
    return "Entailment" if "Confidential Information" in "All Confidential Information shall remain the property of Tompkins Cortland Community College." else "NotMentioned"

@rule("s6", "s1", otherwise="NotMentioned")
def protection_of_confidential_information():
    return "Entailment" if "Confidential Information" in "The Company agrees that for Confidential Information it shall use the same degree of care and means it utilizes to protect its own information of a similar nature, but in any event not less than reasonable care and means, to prevent unauthorized use or disclosure of such Confidential Information to third parties." else "NotMentioned"

@rule("s7", "s1", otherwise="NotMentioned")
def return_or_destroy_confidential_information():
    return "Entailment" if "Confidential Information" in "Upon request of Tompkins Cortland Community College, the Company shall promptly return all copies of the Confidential Information, in whatever form or media, to Tompkins Cortland Community College, or certify the destruction of all such Confidential Information." else "NotMentioned"

@rule("s8", "s1", otherwise="NotMentioned")
def enforceability_of_agreement():
    return "Entailment" if "Confidential Information" in "If any of this Agreement is held to be unenforceable, such unenforceable part shall be deemed modified or eliminated to the extent necessary to make the remaining parts enforceable." else "NotMentioned"

@rule("s9", "s1", otherwise="NotMentioned")
def waiver_of_default():
    return "Entailment" if "Confidential Information" in "Any waiver of a default in performance hereunder shall be deemed a waiver of the particular instance only and shall not be deemed consent to continuing default." else "NotMentioned"

@rule("s10", "s1", otherwise="NotMentioned")
def equitable_relief():
    return "Entailment" if "Confidential Information" in "Company agrees that there may not be an adequate remedy at law for any breach of the obligations hereunder and upon any such breach or any threat thereof by Company, Tompkins Cortland Community College shall be entitled to seek appropriate equitable relief without necessity of posting bond, in addition to whatever other remedies it might be entitled" else "NotMentioned"

@rule("s11", "s1", otherwise="NotMentioned")
def governing_law_and_entire_agreement():
    return "Entailment" if "Confidential Information" in "This Agreement shall be governed by and construed in accordance with the laws of the state of New York, without regard to its conflict of law provisions. Neither Party may assign its rights or delegate its duties or obligations under this Agreement without the other Party’s prior written consent. This Agreement constitutes the entire agreement of the Parties with respect to the subject matter and supersedes all prior agreements or understandings, written or oral, between the Parties with respect thereto." else "NotMentioned"

@rule("s12", "s1", otherwise="NotMentioned")
def compliance_with_laws():
    return "Entailment" if "Confidential Information" in "All laws governing the \"Confidential Information\" of the College, including FERPA - Family Educational Rights and Privacy Act, HIPPA - Health Insurance Portability Act, Gramm-Leach-Bliley Act, New York State Information Security Breach and Notification Act, Sarbanes-Oxley Act and others that may apply will be strictly followed." else "NotMentioned"

@rule("s13", "s1", otherwise="NotMentioned")
def breach_notification():
    return "Entailment" if "Confidential Information" in "Company shall comply with the provisions of the New York State Information Security Breach and Notification Act (General Business Law Section 889-aa; State Technology Law Section 208). Company shall be liable for the costs associated with such breach if caused by Company's negligent or willful acts or omissions, or the negligent or willful acts or omissions of Company's agents, officers, employees or subcontractors." else "NotMentioned"

@rule("s14", "s1", otherwise="NotMentioned")
def signing_of_agreement():
    return "Entailment" if "Confidential Information" in "IN WITNESS WHEREOF, the Parties have caused this Agreement to be signed by their duly authorized representatives." else "NotMentioned"

@rule("s15", "s1", otherwise="NotMentioned")
def signatures_of_parties():
    return "Entailment" if "Confidential Information" in "Tompkins Cortland Community College, SUNY Company: _______________" else "NotMentioned"

@rule("s16", "s1", otherwise="NotMentioned")
def signatures_of_parties():
    return "Entailment" if "Confidential Information" in "Signature: ____________________________ Signature: ____________________________" else "NotMentioned"

@rule("s17", "s1", otherwise="NotMentioned")
def names_of_parties():
    return "Entailment" if "Confidential Information" in "Name: _______________________________ Name: _______________________________" else "NotMentioned"

@rule("s18", "s1", otherwise="NotMentioned")
def titles_of_parties():
    return "Entailment" if "Confidential Information" in "Title: _________________________________ Title: _______________________________" else "NotMentioned"

@rule("s19", "s1", otherwise="NotMentioned")
def dates_of_signing():
    return "Entailment" if "Confidential Information" in "Date:___________________________________ Date:__________________________________" else "NotMentioned"

